pre.code:
/* 用户消息：右下角尖角 */
.message.user .message-text {
  border-radius: 12px 12px 2px 12px;
}

/* AI 消息：左下角尖角 */
.message.assistant .message-text {
  border-radius: 12px 12px 12px 2px;
}

/* 用户消息：反向排列（头像在右） */
.message.user {
  flex-direction: row-reverse;
}

/* AI 消息：正常排列（头像在左） */
.message.assistant {
  flex-direction: row;
}

.chat-page {
  display: flex;
  flex-direction: column;
  height: 100vh;
  padding: 32px;
}

.chat-container {
  flex: 1;
  overflow-y: auto;
}
